/**
 * Helpers for live movement generated by the local motion service: the assistant writes
 * {move:<description>} and the main process streams back .vrma chunks to play as they arrive.
 */
import type { AvatarAnimationBus } from './animation-bus.js';
import type { AvatarMotionChunkEvent } from './types.js';

export const LIVE_MOTION_SOURCE = 'live-motion';

const DEFAULT_REPEAT_WINDOW_MS = 5000;

export function liveMotionSlug(streamId: string, index: number): string {
  return `live-${streamId}-${index}`;
}

export function base64ToArrayBuffer(base64: string): ArrayBuffer {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes.buffer;
}

export function enqueueMotionChunk(bus: AvatarAnimationBus, chunk: AvatarMotionChunkEvent): void {
  bus.enqueue({
    slug: liveMotionSlug(chunk.streamId, chunk.index),
    intent: 'play',
    source: LIVE_MOTION_SOURCE,
    vrmaBinary: base64ToArrayBuffer(chunk.data),
  });
}

/**
 * Realtime text arrives as deltas and again as the completed message, so the same tag can be
 * seen twice. Only the first sighting of a description within the window starts a movement.
 */
export class MoveRequestFilter {
  private readonly recent = new Map<string, number>();

  constructor(
    private readonly windowMs = DEFAULT_REPEAT_WINDOW_MS,
    private readonly now: () => number = Date.now,
  ) {}

  shouldStart(description: string): boolean {
    const key = description.toLowerCase();
    const time = this.now();
    for (const [entry, seenAt] of this.recent) {
      if (time - seenAt > this.windowMs) {
        this.recent.delete(entry);
      }
    }
    if (this.recent.has(key)) {
      return false;
    }
    this.recent.set(key, time);
    return true;
  }
}
